session = (
    [Cmd(start_token, {})] * (window_len - 1)
    + session
    + [Cmd(end_token, {})] * (window_len - 1)
)

likelihoods = []

for i in range(window_len - 1, len(session) - window_len + 1):
    window_likelihood = 0.0

    for j in range(i - (window_len - 1), i + 1):
        cmd = session[j].name

        prior_prob = (
            prior_probs[cmd] if isinstance(prior_probs, dict) else prior_probs[cmd]
        )
        window_likelihood += math.log(prior_prob)

        if j > i - (window_len - 1):
            trans_prob = (
                trans_probs[(session[j - 1].name, cmd)]
                if isinstance(trans_probs, dict)
                else trans_probs[(session[j - 1].name, cmd)]
            )
            window_likelihood += math.log(trans_prob)

        params = session[j].params
        for param in modellable_params:
            if param not in params:
                continue

            param_cond_cmd_prob = (
                param_cond_cmd_probs[(param, cmd)]
                if isinstance(param_cond_cmd_probs, dict)
                else param_cond_cmd_probs[(param, cmd)]
            )
            window_likelihood += math.log(param_cond_cmd_prob)

            value = params[param]
            value_cond_param_prob = (
                value_cond_param_probs[(value, param)]
                if isinstance(value_cond_param_probs, dict)
                else value_cond_param_probs[(value, param)]
            )
            window_likelihood += math.log(value_cond_param_prob)

    likelihoods.append(window_likelihood / (window_len if use_geo_mean else 1))

return likelihoods

def mkdir(self, path):
    hadoop_version = self._get_hadoop_version()

    cmd = ["hdfs", "fs", "-mkdir"]
    if self.uses_yarn(hadoop_version):
        cmd += ["-p"]

    cmd += [path]

    try:
        subprocess.check_call(cmd, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        if "already exists" not in str(e.output):
            raise IOError("Could not mkdir {}".format(path))


def _get_hadoop_version(self):
    cmd = ["hdfs", "--version"]
    output = subprocess.check_output(cmd)

    for line in output.decode("utf-8").splitlines():
        if "Hadoop" in line:
            return line.split()[1]


@staticmethod
def uses_yarn(version):
    """Basically, is this Hadoop 2? This also handles versions in the
    zero series (0.23+) where YARN originated."""

    return (
        HadoopFilesystem._version_gte(version, "2")
        or HadoopFilesystem._version_gte(version, "0.23")
        and not HadoopFilesystem._version_gte(version, "1")
    )


@staticmethod
def _version_gte(haystack, needle):
    """True if version string 'haystack' is >= to version 'needle'. Both
    are strings.
    >>> HadoopFilesystem._version_gte('0.23', '0.18')
    True"""
    return haystack.split(".") >= needle.split(".")

