@staticmethod
def parse_string(chord):
    roman_numeral = chord[0]
    acc = 0
    suffix = ""
    if len(chord) > 1:
        if chord[1].lower() == "b":
            acc -= 1
            roman_numeral = chord[2]
        elif chord[1].lower() == "#":
            acc += 1
            roman_numeral = chord[2]
    return (roman_numeral, acc, suffix)


def from_progression_shorthand(self, shorthand, key="C"):
    progression = [x.strip() for x in shorthand.split("-") if x.strip() != ""]
    notes = []
    for chord in progression:
        (roman_numeral, acc, suffix) = NoteContainer.parse_string(chord)
        r = chords.__dict__[roman_numeral](key)
        while acc < 0:
            r = [notes.diminish(x) for x in r]
            acc += 1
        while acc > 0:
            r = [notes.augment(x) for x in r]
            acc -= 1
        notes += r
    self._notes = notes
    return self

