@staticmethod
def _parse_narrow_link(cls, link: str) -> Dict[str, Any]:
    narrow = {}

    regexes = [
        r"^stream/([0-9]+)-(.+?)$",  # a. stream/[{stream_id}-]{stream-name}
        r"^stream/([0-9]+)-(.+?)/near/(\d+)$",  # b. stream/[{stream_id}-]{stream-name}/near/{message_id}
        r"^stream/([0-9]+)-(.+?)/topic/(.+?)$",  # c. stream/[{stream_id}-]{stream-name}/topic/{encoded.20topic.20name}
        r"^stream/([0-9]+)-(.+?)/topic/(.+?)/near/(\d+)$",  # d. stream/[{stream_id}-]{stream-name}/topic/{encoded.20topic.20name}/near/{message_id}
    ]

    for regex in regexes:
        match = re.match(regex, link)

        if match is not None:
            groups = match.groups()

            narrow["stream_id"] = int(groups[0])
            narrow["stream_name"] = cls.hash_util_decode(groups[1])

            if len(groups) > 2:  # has topic and/or message_id
                narrow["topic"] = cls.hash_util_decode(groups[-2])

                if groups[-1].isdigit():  # has message_id
                    narrow["message_id"] = int(groups[-1])

            return narrow

    return {}

