"""Normalize a path by collapsing back-references (such as "..") and removing duplicated separators ("/"). If the input describes a path that can not be reached, such as "foo/../../bar", an IndexError will be excepted and the function will raise an illegal back reference instead."""

# Remove duplicate slashes
while "//" in path:
    path = path.replace("//", "/")

# Split path into parts
parts = path.split("/")[1:]

# Process each part
normalized_parts = []
for part in parts:
    if part == "..":
        try:
            normalized_parts.pop()  # Remove previous component
        except IndexError:
            raise IllegalBackReference(path)
    elif part != ".":
        normalized_parts.append(part)

return "/" + "/".join(normalized_parts)

