def deserialize(self, value, display=False):
    if isinstance(value, str):
        value = bytes(value, "utf-8").decode("idna")

    # Strip whitespace
    value = value.strip()

    # Check for Unix socket path and convert to string representation
    unix_socket_path = self._get_unix_socket_path(value)
    if unix_socket_path is not None:
        return str(unix_socket_path)

    # Check for valid hostname or IP address using regex
    pattern = r"^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\-]*[a-zA-Z0-9])\.)+([A-Za-z]|[A-Za-z][A-Za-z0-9\-]*[A-Za-z0-9])$"
    if not re.match(pattern, value):
        raise ValueError("Invalid hostname or IP address.")

    return value


def _get_unix_socket_path(self, value):
    match = re.search("^unix:(.*)", value)
    if match:
        unix_socket_path = match.group(1)
        return str(unix_socket_path)
    return None

