    prior = np.prod([prior_probs[cmd] for cmd in window[:-1]])

    trans = (
        1
        if len(window) < 2
        else np.prod([trans_probs[pair] for pair in zip(window, window[1:])])
    )
    likelihood = prior * trans
    window_likelihoods.append((list(window), likelihood))

