        [
            trans_probs[pair]
            for pair in zip(min_likelihood_window[:-1], min_likelihood_window[1:])
        ]
    ) ** (1 / window_len)
    return min_likelihood_window, geo_mean_likelihood

return min_likelihood_window, _

