def __init__(self, stream):
    super().__init__(stream)
    self._buf = BytesIO()
    self._finish = False


def read(self, size):
    if not isinstance(size, int):
        raise TypeError("Size must be an integral type")

    if size < 0:
        raise ValueError("Size must be positive.")

    if size == 0:
        return b""

    self._buf.seek(0, os.SEEK_END)

    while self._buf.tell() < size:
        chunk = super().chunk()
        if not chunk and not self._finish:
            self._finish = True
        elif not chunk:
            break
        else:
            self._buf.write(chunk)

    data = self._buf.getvalue()
    remaining_data = data[size:]

    self._buf = BytesIO()
    if remaining_data:  # add the remainder to new buffer
        self._buf.write(remaining_data)

    return data[:size]

