def get_assign_targets_with_attr(self, node: ast.AST) -> List[ast.Attribute]:
    if isinstance(node, ast.Assign):
        return self._get_nodes_of_type(node.targets, ast.Attribute)

    elif isinstance(node, (ast.Expr, ast.If, ast.While)):
        # If/while nodes have a body which may contain Assign nodes
        return self._get_assignments(node.body)

    elif isinstance(node, (ast.Module, ast.FunctionDef, ast.ClassDef)):
        return self._get_nodes_of_type(node.body, ast.Assign)

    else:
        print(
            "WARNING Unexpected node type {} for ast.Assign. Please report to the author github.com/gaogaotiantian/viztracer".format(
                type(node)
            )
        )

    return []


def _get_nodes_of_type(self, nodes: List[ast.AST], node_type):
    results = []

    for n in nodes:
        if isinstance(n, (list, tuple)):
            # Recurse into lists and tuples
            results += self._get_nodes_of_type(n, node_type)

        elif isinstance(n, node_type):
            results.append(n)

    return results


def _get_assignments(self, body: List[ast.AST]) -> List[ast.Attribute]:
    assignments = []

    for stmt in body:
        # Recurse into nodes of interest within a statement (like If or Assign)
        if isinstance(stmt, (ast.Assign, ast.If, ast.Expr)):
            assignments += self.get_assign_targets_with_attr(stmt)

    return assignments

