for addr in conf.address():
    try:
        if isinstance(addr, tuple) and len(addr) == 2:
            # Create a TCP socket
            family, address = addr

            sock_type = socket.SOCK_STREAM if family == "inet" else socket.SOCK_DGRAM
            s = socket.socket(sock.util.get_family(family), sock_type)
            s.setblocking(0)

            try:
                # Set SSL options for the socket
                if conf.settings["keyfile"]:
                    log.info(
                        "Loading SSL certificate and key from %s",
                        conf.settings["certfile"],
                    )

                    context = sock.ssl.SSLContext(conf.settings["ssl_version"])
                    context.load_cert_chain(
                        conf.settings["certfile"], conf.settings["keyfile"]
                    )

                if conf.settings["ca_certs"]:
                    context.verify_mode = ssl.CERT_REQUIRED
                    context.load_verify_locations(conf.settings["ca_certs"])
            except Exception as e:
                log.error("Error loading SSL certificate", exc_info=e)

            # Bind the socket to the address
            s.bind(address)
            sockets.append(s)
        else:
            # Create a Unix socket
            s = socket.socket(family=socket.AF_UNIX, type=socket.SOCK_STREAM)

            try:
                s.connect(addr)
            except Exception as e:
                log.error("Error connecting to Unix socket", exc_info=e)

            sockets.append(s)
    except Exception as e:
        log.error("Exception during socket creation", exc_info=True)

return sockets

