self.session_likelihood = {}
for sid, session in self.sessions.items():
    likelihood = 1.0
    if use_start_end_tokens:
        session = ["<START>"] + session + ["<END>"]
    for event in session:
        if event not in self.transition_matrix:
            continue
        likelihood *= np.max(self.transition_matrix[event])

    # store the likelihood in the dictionary
    self.session_likelihood[sid] = likelihood

# calculate geometric mean of the likelihoods for each session
geom_mean = stats.gmean(
    [likelihood for _, likelihood in self.session_likelihood.items()]
)

# use a sliding window approach to compute rarest window likelihoods
self.rare_window_likelihood = {}
for sid, session in self.sessions.items():
    if use_start_end_tokens:
        session = ["<START>"] + session + ["<END>"]

    min_likelihood = np.inf
    window_length = (
        2 if len(session) > 3 else len(session)
    )  # to handle sessions of length less than or equal to 3
    for i in range(len(session) - window_length + 1):
        likelihood = 1.0
        for event in session[i : i + window_length]:
            if event not in self.transition_matrix:
                continue
            likelihood *= np.max(self.transition_matrix[event])

        min_likelihood = min(min_likelihood, likelihood)

    # store the rarest window likelihood for this session
    self.rare_window_likelihood[sid] = (
        min_likelihood
        if not use_start_end_tokens
        else np.nan if len(session) < 4 else min_likelihood
    )

