for i in range(len(session) - window_len + 1):
    likelihood = 1.0
    for j in range(window_len):
        cmd = session[i + j].name
        if j == 0:
            likelihood *= prior_probs[cmd]
        else:
            prev_cmd = session[i + j - 1].name
            likelihood *= trans_probs[prev_cmd][cmd]

        for param in session[i + j].params:
            likelihood *= param_cond_cmd_probs[param][cmd]

    if use_geo_mean:
        likelihood = likelihood ** (1.0 / window_len)

    likelihoods.append(likelihood)

return likelihoods

